dashboard.definition:
{
 "title": "Firewall Posture",
 "description": "Current configuration state of every host: compliance gauges per profile, collection blind spots, posture drift and the risky rule inventory.",
 "visualizations": {
  "hdr": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "## Firewall Posture\nState, not events. An event stream cannot tell you that a host had its firewall off *before* Splunk arrived, nor that a silent host is silent because drop logging is disabled rather than because nothing happened.\n\nNeeds the companion **TA-windows-firewall-posture** on the forwarders.",
    "fontSize": "large",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "kpi_hosts": {
   "type": "splunk.singlevalue",
   "title": "Hosts inventoried",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('hosts') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#4fa3ff"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "kpi_compliance": {
   "type": "splunk.singlevalue",
   "title": "Compliance",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('compliance_pct') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 1,
    "majorColor": "> majorValue | rangeValue(majorColorConfig)",
    "unit": "%",
    "unitPosition": "after"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "majorColorConfig": [
     {
      "to": 80,
      "value": "#e5484d"
     },
     {
      "from": 80,
      "to": 95,
      "value": "#f5a623"
     },
     {
      "from": 95,
      "value": "#2fb67c"
     }
    ]
   }
  },
  "kpi_disabled": {
   "type": "splunk.singlevalue",
   "title": "Firewall off",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('disabled_hosts') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "> majorValue | rangeValue(majorColorConfig)"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "majorColorConfig": [
     {
      "to": 1,
      "value": "#2fb67c"
     },
     {
      "from": 1,
      "value": "#e5484d"
     }
    ]
   }
  },
  "kpi_nolog": {
   "type": "splunk.singlevalue",
   "title": "Drop logging off",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('no_logging_hosts') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "> majorValue | rangeValue(majorColorConfig)"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "majorColorConfig": [
     {
      "to": 1,
      "value": "#2fb67c"
     },
     {
      "from": 1,
      "value": "#f5a623"
     }
    ]
   },
   "description": "These hosts will never appear in the traffic dashboards, whatever they do on the network."
  },
  "kpi_inbound": {
   "type": "splunk.singlevalue",
   "title": "Default inbound allow",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('inbound_allow_hosts') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "> majorValue | rangeValue(majorColorConfig)"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "majorColorConfig": [
     {
      "to": 1,
      "value": "#2fb67c"
     },
     {
      "from": 1,
      "value": "#e5484d"
     }
    ]
   }
  },
  "kpi_noncompliant": {
   "type": "splunk.singlevalue",
   "title": "Hosts with findings",
   "dataSources": {
    "primary": "ds_kpi"
   },
   "options": {
    "majorValue": "> primary | seriesByName('noncompliant_hosts') | lastPoint()",
    "backgroundColor": "transparent",
    "numberPrecision": 0,
    "majorColor": "#f5a623"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "hdr_gauge": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Compliance per profile\nOne gauge per firewall profile. Public is usually the one that drifts.",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_gauge": {
   "type": "splunk.fillergauge",
   "title": "",
   "dataSources": {
    "primary": "ds_gauge_profile"
   },
   "options": {
    "value": "> primary | seriesByName('compliance') | lastPoint()",
    "gaugeColor": "> value | rangeValue(complianceColorConfig)",
    "orientation": "vertical",
    "valueDisplay": "number",
    "splitByLayout": "trellis",
    "trellisSplitBy": "profile",
    "trellisMinColumnWidth": 260,
    "trellisRowHeight": 240,
    "trellisPageCount": 6,
    "backgroundColor": "transparent"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "severityBgConfig": [
     {
      "match": "critical",
      "value": "#4a1015"
     },
     {
      "match": "high",
      "value": "#3a1d20"
     },
     {
      "match": "medium",
      "value": "#3a2c17"
     },
     {
      "match": "informational",
      "value": "#1c2229"
     }
    ],
    "complianceColorConfig": [
     {
      "to": 80,
      "value": "#e5484d"
     },
     {
      "from": 80,
      "to": 95,
      "value": "#f5a623"
     },
     {
      "from": 95,
      "value": "#2fb67c"
     }
    ]
   }
  },
  "hdr_state": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Where the estate stands",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_matrix": {
   "type": "splunk.column",
   "title": "Posture by profile",
   "dataSources": {
    "primary": "ds_matrix"
   },
   "options": {
    "stackMode": "stacked",
    "seriesColors": [
     "#2fb67c",
     "#e5484d",
     "#f5a623",
     "#a175ff",
     "#8c9199"
    ],
    "legendDisplay": "bottom",
    "yAxisTitleText": "Hosts",
    "xAxisTitleText": "",
    "backgroundColor": "transparent"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "viz_findings": {
   "type": "splunk.bar",
   "title": "Findings across the estate",
   "dataSources": {
    "primary": "ds_findings"
   },
   "options": {
    "seriesColors": [
     "#f5a623"
    ],
    "legendDisplay": "off",
    "xAxisTitleText": "Hosts affected",
    "yAxisTitleText": "",
    "backgroundColor": "transparent"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "hdr_off": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Hosts to fix first — click a row to open its 360 view",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_offenders": {
   "type": "splunk.table",
   "title": "Non compliant hosts",
   "dataSources": {
    "primary": "ds_offenders"
   },
   "options": {
    "count": 14,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true,
    "columnFormat": {
     "severity": {
      "rowBackgroundColors": "> table | seriesByName(\"severity\") | matchValue(severityBgConfig)"
     }
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "severityBgConfig": [
     {
      "match": "critical",
      "value": "#4a1015"
     },
     {
      "match": "high",
      "value": "#3a1d20"
     },
     {
      "match": "medium",
      "value": "#3a2c17"
     },
     {
      "match": "informational",
      "value": "#1c2229"
     }
    ],
    "complianceColorConfig": [
     {
      "to": 80,
      "value": "#e5484d"
     },
     {
      "from": 80,
      "to": 95,
      "value": "#f5a623"
     },
     {
      "from": 95,
      "value": "#2fb67c"
     }
    ]
   },
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_host_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_host=$row.Computer.value$",
      "newTab": false
     }
    }
   ]
  },
  "hdr_blind": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Collection blind spots\nThese hosts are configured in a way that guarantees an empty traffic dashboard. Fix them before trusting any coverage number.",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_blind": {
   "type": "splunk.table",
   "title": "",
   "dataSources": {
    "primary": "ds_blind"
   },
   "options": {
    "count": 12,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_host_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_host=$row.Computer.value$",
      "newTab": false
     }
    }
   ]
  },
  "viz_drift": {
   "type": "splunk.timeline",
   "title": "Posture drift over time",
   "dataSources": {
    "primary": "ds_drift"
   },
   "options": {
    "backgroundColor": "transparent",
    "legendDisplay": "right",
    "category": "> primary | seriesByName('state')",
    "seriesColors": [
     "#2fb67c",
     "#e5484d",
     "#4fa3ff",
     "#f5a623",
     "#a175ff",
     "#31c2c9",
     "#e05f9e",
     "#8c9199"
    ]
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "description": "Every transition between enabled and disabled that the inventory captured.",
   "hideWhenNoData": true
  },
  "hdr_rules": {
   "type": "splunk.markdown",
   "options": {
    "markdown": "### Rule inventory\nInbound allow rules open to any address, on any port, with no application binding are the shape worth hunting.",
    "fontSize": "medium",
    "fontColor": "#dbe0e6",
    "backgroundColor": "transparent"
   }
  },
  "viz_rule_graph": {
   "type": "splunk.networkGraph",
   "title": "Hosts and the risks their rules carry",
   "dataSources": {
    "primary": "ds_rule_graph"
   },
   "options": {
    "layout": "hierarchical",
    "linkStyle": "z",
    "linkDirection": "one-way",
    "nodeColors": "#e5484d",
    "backgroundColor": "transparent",
    "nodeHorizontalPadding": 60,
    "linkValues": "> primary | seriesByName('linkValues')"
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "hideWhenNoData": true
  },
  "viz_rule_risk": {
   "type": "splunk.bar",
   "title": "Rule risks across the estate",
   "dataSources": {
    "primary": "ds_rule_risk_summary"
   },
   "options": {
    "seriesColors": [
     "#e5484d"
    ],
    "legendDisplay": "off",
    "xAxisTitleText": "Rules",
    "yAxisTitleText": "",
    "backgroundColor": "transparent"
   },
   "showProgressBar": false,
   "showLastUpdated": false
  },
  "viz_rule_volume": {
   "type": "splunk.table",
   "title": "Hosts with the most inbound allow rules",
   "dataSources": {
    "primary": "ds_rule_volume"
   },
   "options": {
    "count": 12,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "eventHandlers": [
    {
     "type": "drilldown.customUrl",
     "options": {
      "url": "/app/windows_firewall_app/windows_firewall_host_view?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$&form.tk_host=$row.Computer.value$",
      "newTab": false
     }
    }
   ]
  },
  "viz_risky_rules": {
   "type": "splunk.table",
   "title": "Risky rules",
   "dataSources": {
    "primary": "ds_risky_rules"
   },
   "options": {
    "count": 25,
    "dataOverlayMode": "none",
    "backgroundColor": "transparent",
    "tableFormat": {
     "rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByBackgroundColor)"
    },
    "showRowNumbers": true,
    "columnFormat": {
     "severity": {
      "rowBackgroundColors": "> table | seriesByName(\"severity\") | matchValue(severityBgConfig)"
     }
    }
   },
   "showProgressBar": false,
   "showLastUpdated": false,
   "context": {
    "severityBgConfig": [
     {
      "match": "critical",
      "value": "#4a1015"
     },
     {
      "match": "high",
      "value": "#3a1d20"
     },
     {
      "match": "medium",
      "value": "#3a2c17"
     },
     {
      "match": "informational",
      "value": "#1c2229"
     }
    ],
    "complianceColorConfig": [
     {
      "to": 80,
      "value": "#e5484d"
     },
     {
      "from": 80,
      "to": 95,
      "value": "#f5a623"
     },
     {
      "from": 95,
      "value": "#2fb67c"
     }
    ]
   },
   "eventHandlers": [
    {
     "type": "drilldown.linkToSearch",
     "options": {
      "type": "auto",
      "newTab": true
     }
    }
   ]
  }
 },
 "dataSources": {
  "ds_computer_list": {
   "type": "ds.search",
   "options": {
    "query": "`wfo_posture_profiles` | stats count BY Computer | fields Computer | sort Computer"
   },
   "name": "Computers"
  },
  "ds_profiles": {
   "type": "ds.search",
   "options": {
    "query": "`wfo_posture_profiles` | search Computer IN ($ms_computer$) | fields _time _raw host source sourcetype index Computer OVER compliance compliance_pct compliant default_inbound_action default_outbound_action disabled_hosts duration enabled finding finding_count findings firewall_service hosts inbound_allow_hosts last_seen log_allowed log_blocked log_file_name log_file_present log_file_size_kb log_max_size_kb no_logging_hosts noncompliant_hosts occurrences ok profile profiles severity state"
   },
   "name": "Profile posture"
  },
  "ds_rules": {
   "type": "ds.search",
   "options": {
    "query": "`wfo_posture_rules` | search Computer IN ($ms_computer$) | fields _time _raw host source sourcetype index Computer direction hosts inbound_allow linkValues local_port policy_source profile_name program remote_address risk risks rule_action rule_name rules severity target"
   },
   "name": "Rule inventory"
  },
  "ds_current": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_profiles",
    "query": "| stats latest(_time) AS _time, latest(enabled) AS enabled, latest(default_inbound_action) AS default_inbound_action, latest(default_outbound_action) AS default_outbound_action, latest(log_allowed) AS log_allowed, latest(log_blocked) AS log_blocked, latest(log_max_size_kb) AS log_max_size_kb, latest(log_file_present) AS log_file_present, latest(log_file_name) AS log_file_name, latest(log_file_size_kb) AS log_file_size_kb, latest(firewall_service) AS firewall_service, latest(compliant) AS compliant, latest(findings) AS findings, latest(finding_count) AS finding_count BY Computer, profile "
   },
   "name": "Current profile state"
  },
  "ds_kpi": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_current",
    "query": "| stats dc(Computer) AS hosts, dc(eval(if(enabled!=\"true\", Computer, null()))) AS disabled_hosts, dc(eval(if(log_blocked!=\"true\", Computer, null()))) AS no_logging_hosts, dc(eval(if(default_inbound_action=\"allow\", Computer, null()))) AS inbound_allow_hosts, dc(eval(if(compliant!=\"true\", Computer, null()))) AS noncompliant_hosts | eval compliance_pct = if(hosts>0, round((hosts-noncompliant_hosts)*100/hosts, 1), 0)"
   },
   "name": "KPI"
  },
  "ds_gauge_profile": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_current",
    "query": "| stats dc(Computer) AS hosts, dc(eval(if(compliant=\"true\", Computer, null()))) AS ok BY profile | eval compliance = if(hosts>0, round(ok*100/hosts, 1), 0) | fields profile compliance"
   },
   "name": "Compliance per profile"
  },
  "ds_offenders": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_current",
    "query": "| where compliant!=\"true\" | stats values(profile) AS profiles, values(findings) AS findings, sum(finding_count) AS finding_count, max(_time) AS last_seen BY Computer | eval last_seen = strftime(last_seen, \"%F %T\"), severity = case(match(mvjoin(findings,\",\"), \"firewall_disabled\"), \"critical\", match(mvjoin(findings,\",\"), \"default_inbound_allow\"), \"critical\", match(mvjoin(findings,\",\"), \"dropped_packets_not_logged\"), \"high\", true(), \"medium\") | table Computer severity profiles findings finding_count last_seen | sort - finding_count"
   },
   "name": "Non compliant hosts"
  },
  "ds_matrix": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_current",
    "query": "| eval state = case(enabled!=\"true\",\"firewall off\", default_inbound_action=\"allow\",\"inbound allow\", log_blocked!=\"true\",\"no drop logging\", compliant=\"true\",\"compliant\", true(),\"minor findings\") | chart count OVER profile BY state"
   },
   "name": "Posture by profile"
  },
  "ds_findings": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_current",
    "query": "| eval finding = split(findings, \",\") | mvexpand finding | where finding!=\"\" AND finding!=\"-\" | stats dc(Computer) AS hosts, count AS occurrences BY finding | sort - hosts"
   },
   "name": "Findings"
  },
  "ds_blind": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_current",
    "query": "| where log_blocked!=\"true\" OR log_file_present!=\"true\" | stats values(profile) AS profiles, latest(log_blocked) AS log_blocked, latest(log_file_present) AS log_file_present, latest(log_file_name) AS log_file_name, latest(log_max_size_kb) AS log_max_size_kb BY Computer | sort Computer"
   },
   "name": "Blind spots"
  },
  "ds_drift": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_profiles",
    "query": "| eval state = if(enabled=\"true\", \"enabled\", \"disabled\"), duration = 0 | table _time Computer duration state | sort _time | head 300"
   },
   "name": "Posture drift"
  },
  "ds_rules_latest": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_rules",
    "query": "| stats latest(_time) AS _time, latest(risks) AS risks, latest(severity) AS severity, latest(direction) AS direction, latest(rule_action) AS rule_action, latest(local_port) AS local_port, latest(remote_address) AS remote_address, latest(program) AS program, latest(profile_name) AS profile_name, latest(policy_source) AS policy_source BY Computer, rule_name | where risks!=\"-\" AND risks!=\"\" "
   },
   "name": "Risky rules"
  },
  "ds_risky_rules": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_rules_latest",
    "query": "| table Computer severity rule_name direction rule_action local_port remote_address program profile_name policy_source risks | sort severity, Computer | head 50"
   },
   "name": "Risky rules table"
  },
  "ds_rule_risk_summary": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_rules_latest",
    "query": "| eval risk = split(risks, \",\") | mvexpand risk | where risk!=\"\" AND risk!=\"-\" | stats dc(Computer) AS hosts, count AS rules BY risk | sort - rules"
   },
   "name": "Risk summary"
  },
  "ds_rule_volume": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_rules",
    "query": "| stats dc(rule_name) AS rules, dc(eval(if(direction=\"inbound\" AND rule_action=\"allow\", rule_name, null()))) AS inbound_allow BY Computer | sort - inbound_allow | head 20"
   },
   "name": "Rules per host"
  },
  "ds_rule_graph": {
   "type": "ds.chain",
   "options": {
    "extend": "ds_rules_latest",
    "query": "| eval risk = split(risks, \",\") | mvexpand risk | where risk!=\"\" AND risk!=\"-\" | stats count AS linkValues BY Computer, risk | rename Computer AS source, risk AS target | sort - linkValues | head 60 | appendpipe [| stats count BY target | rename target AS source | fields source] | table source target linkValues"
   },
   "name": "Host to risk graph"
  }
 },
 "inputs": {
  "input_time": {
   "type": "input.timerange",
   "title": "Time range",
   "options": {
    "token": "global_time",
    "defaultValue": "-24h@h,now"
   }
  },
  "input_computer": {
   "type": "input.multiselect",
   "title": "Computer",
   "dataSources": {
    "primary": "ds_computer_list"
   },
   "options": {
    "items": ">frame(label, value) | prepend(formattedStatics) | objects()",
    "token": "ms_computer",
    "defaultValue": [
     "*"
    ],
    "valuePrefix": "\"",
    "valueSuffix": "\"",
    "delimiter": ","
   },
   "context": {
    "formattedConfig": {
     "number": {
      "prefix": ""
     }
    },
    "formattedStatics": ">statics | formatByType(formattedConfig)",
    "statics": [
     {
      "label": "All",
      "value": "*"
     }
    ],
    "label": ">primary | seriesByName(\"Computer\") | renameSeries(\"label\") | formatByType(formattedConfig)",
    "value": ">primary | seriesByName(\"Computer\") | renameSeries(\"value\") | formatByType(formattedConfig)"
   }
  }
 },
 "layout": {
  "tabs": {
   "items": [
    {
     "layoutId": "layout_compliance",
     "label": "Compliance"
    },
    {
     "layoutId": "layout_blind",
     "label": "Blind spots"
    },
    {
     "layoutId": "layout_rules",
     "label": "Rule inventory"
    }
   ]
  },
  "layoutDefinitions": {
   "layout_compliance": {
    "type": "grid",
    "options": {
